(function(root){
'use strict';
function cents(v){if(!/^\d{1,8}(\.\d{1,2})?$/.test(String(v)))throw Error('Enter a positive amount with at most two decimals.');const [a,b='']=String(v).split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n)||n<=0)throw Error('Amount must be greater than zero.');return n;}
function split(total,ids,mode,values=[]){if(!Number.isSafeInteger(total)||total<=0||!ids.length||new Set(ids).size!==ids.length)throw Error('Invalid amount or participants.');let weights;
if(mode==='exact'){const out=values.map(cents);if(out.length!==ids.length||out.reduce((a,b)=>a+b,0)!==total)throw Error('Exact amounts must match the expense total.');return Object.fromEntries(ids.map((id,i)=>[id,out[i]]));}
if(mode==='equal')weights=ids.map(()=>1);else if(mode==='percentage'){weights=values.map(v=>{if(!/^\d{1,3}(\.\d{1,2})?$/.test(String(v)))throw Error('Use percentages with at most two decimals.');return Math.round(Number(v)*100);});if(weights.reduce((a,b)=>a+b,0)!==10000)throw Error('Percentages must total 100.');}else if(mode==='shares'){weights=values.map(v=>{if(!/^\d{1,6}$/.test(String(v))||Number(v)<1)throw Error('Shares must be positive whole numbers.');return Number(v);});}else throw Error('Unknown split method.');
if(weights.length!==ids.length)throw Error('Enter a value for each participant.');const sum=weights.reduce((a,b)=>a+b,0);const amounts=weights.map(w=>Number(BigInt(total)*BigInt(w)/BigInt(sum)));const order=ids.map((id,i)=>({i,r:BigInt(total)*BigInt(weights[i])%BigInt(sum)})).sort((a,b)=>a.r===b.r?a.i-b.i:a.r>b.r?-1:1);let rest=total-amounts.reduce((a,b)=>a+b,0);for(let i=0;i<rest;i++)amounts[order[i].i]++;return Object.fromEntries(ids.map((id,i)=>[id,amounts[i]]));}
function balances(group){const out=Object.fromEntries(group.members.map(m=>[m.id,0]));for(const e of group.expenses){if(!(e.payer in out)||!Number.isSafeInteger(e.amount)||e.amount<=0||Object.values(e.allocations).reduce((a,b)=>a+b,0)!==e.amount)throw Error('Invalid expense ledger.');out[e.payer]+=e.amount;for(const [id,v]of Object.entries(e.allocations)){if(!(id in out)||!Number.isSafeInteger(v)||v<0)throw Error('Invalid participant.');out[id]-=v;}}for(const r of group.repayments){if(!(r.from in out)||!(r.to in out)||r.from===r.to||!Number.isSafeInteger(r.amount)||r.amount<=0)throw Error('Invalid repayment.');out[r.from]+=r.amount;out[r.to]-=r.amount;}return out;}
function debts(group){const b=balances(group),pos=Object.entries(b).filter(x=>x[1]>0),neg=Object.entries(b).filter(x=>x[1]<0).map(([id,v])=>[id,-v]);let i=0,j=0,out=[];while(i<neg.length&&j<pos.length){const amount=Math.min(neg[i][1],pos[j][1]);out.push({from:neg[i][0],to:pos[j][0],amount});neg[i][1]-=amount;pos[j][1]-=amount;if(!neg[i][1])i++;if(!pos[j][1])j++;}return out;}
const api={cents,split,balances,debts};if(typeof module!=='undefined')module.exports=api;root.Money=api;
})(typeof window!=='undefined'?window:globalThis);
